#!/usr/bin/env python3
"""Print the README results table (Markdown) from results/*.csv.

Every number comes from a file in results/ written by a checked-in script;
nothing is typed by hand.

Usage: scripts/results_table.py [results-dir] [--update-readme README.md]
  --update-readme: replace the block between the "generated by
  scripts/results_table.py" and "end generated" marker comments.
"""
import io
import re
import csv
import os
import sys


def table(d):
    with open(os.path.join(d, "agreement_summary.csv")) as f:
        s = next(csv.DictReader(f))
    with open(os.path.join(d, "collect_summary.csv")) as f:
        kernels = list(csv.DictReader(f))
    print("| Measure (PolyBench/C 4.2.1, clang-20 -O3 -g, x86-64; tuning set: rules were fixed on it) | Value |")
    print("| --- | --- |")
    print("| Kernels compiled | %d |" % len(kernels))
    print("| Innermost loops matched with a LoopVectorize verdict | %s |" % s["loops_both"])
    print("| LoopLens primary = LoopVectorize's first reason | %s (%s%%) |" % (s["agree"], s["agree_pct"]))
    print("| ... or one of LoopLens's secondary categories | %s (%s%%) |"
          % (s["agree_incl_secondary"], s["agree_incl_secondary_pct"]))
    if "all_reasons_covered" in s:
        print("| *every* LoopVectorize reason among LoopLens's categories | %s (%s%%) |"
              % (s["all_reasons_covered"], s["all_reasons_covered_pct"]))
    print("| Loops unmatched / ambiguous | %d / %s |"
          % (int(s["looplens_only"]) + int(s["lv_only"]), s["ambiguous"]))
    print("| LLVM remark names without a mapping | %s |" % (s["unmapped"] or "none"))
    tsvc = os.path.join(d, "tsvc_agreement_summary.csv")
    if os.path.exists(tsvc):
        with open(tsvc) as f:
            t = next(csv.DictReader(f))
        print()
        print("| Second suite (TSVC_2, one file, same flags; untuned first run: results/tsvc_agreement_summary_before.csv) | Value |")
        print("| --- | --- |")
        print("| Innermost loops matched with a LoopVectorize verdict | %s |" % t["loops_both"])
        print("| LoopLens primary = LoopVectorize's first reason | %s (%s%%) |" % (t["agree"], t["agree_pct"]))
        print("| ... or one of LoopLens's secondary categories | %s (%s%%) |"
              % (t["agree_incl_secondary"], t["agree_incl_secondary_pct"]))
        if "all_reasons_covered" in t:
            print("| *every* LoopVectorize reason among LoopLens's categories | %s (%s%%) |"
                  % (t["all_reasons_covered"], t["all_reasons_covered_pct"]))
        print("| Loops unmatched / ambiguous | %d / %s |"
              % (int(t["looplens_only"]) + int(t["lv_only"]), t["ambiguous"]))


def targets_table(d):
    rows = []
    for label, flags, pb, ts in [
            ("x86-64 (generic)", "(default)", "", "tsvc_"),
            ("x86-64-v4 (AVX-512)", "`-march=x86-64-v4`", "x86v4_", "tsvc_x86v4_"),
            ("AArch64", "`--target=aarch64-linux-gnu`", "aarch64_", "tsvc_aarch64_")]:
        cells = []
        for pre in (pb, ts):
            f = os.path.join(d, pre + "agreement_summary.csv")
            if not os.path.exists(f):
                cells.append("n/a")
                continue
            with open(f) as fh:
                t = next(csv.DictReader(fh))
            cells.append("%s / %s (%s%%)" % (t["agree"], t["loops_both"], t["agree_pct"]))
        rows.append((label, flags, cells))
    if all(c == ["n/a", "n/a"] for _, _, c in rows[1:]):
        return
    print()
    print("| Target | Flags | PolyBench agree / loops | TSVC agree / loops |")
    print("| --- | --- | --- | --- |")
    for label, flags, (a, b) in rows:
        print("| %s | %s | %s | %s |" % (label, flags, a, b))


def main(argv):
    readme = None
    if "--update-readme" in argv:
        i = argv.index("--update-readme")
        readme = argv[i + 1]
        argv = argv[:i] + argv[i + 2:]
    d = argv[0] if argv else os.path.join(os.path.dirname(__file__), "..", "results")
    buf = io.StringIO()
    stdout, sys.stdout = sys.stdout, buf
    try:
        table(d)
        targets_table(d)
    finally:
        sys.stdout = stdout
    text = buf.getvalue()
    if readme is None:
        sys.stdout.write(text)
        return 0
    with open(readme) as f:
        content = f.read()
    pat = re.compile(r"(<!-- generated by scripts/results_table.py[^\n]*-->\n).*?(<!-- end generated -->)", re.S)
    if not pat.search(content):
        sys.exit("error: no generated-block markers in " + readme)
    with open(readme, "w") as f:
        f.write(pat.sub(lambda m: m.group(1) + text + m.group(2), content))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
